PortalAdmin = {
    init: async function (app, container ) {
        app = app || session.app;
        container = container || $(".component[name=PortalAdmin]");

        $("[name=tabs]", container).kendoTabStrip({ animation: { open: { effects: "fadeIn" } } });

        await loadComponent($(".tab[name=globalization]", container), "GlobalizationManagement");
        GlobalizationManagement.init(app, $(".component[name=GlobalizationManagement]", container));
        await loadComponent($(".tab[name=systems]", container), "SystemsManagement");
        SystemsManagement.init(app, $(".component[name=SystemsManagement]", container));
        await loadComponent($(".tab[name=companies]", container), "CompanyManagement");
        CompanyManagement.init(app, $(".component[name=CompanyManagement]", container));
        await loadComponent($(".tab[name=rootBuckets]", container), "B2BAdmin");
        B2BAdmin.init(app, $(".component[name=B2BAdmin]", container));
    }
}
